    {
      "ids": ["GRN-07", "TRU-06"],
      "type": "resource",
      "description": "Energy reduction during critical failures (GRN-07) may conflict with the need for secure remote updates (TRU-06), which require system resources."
    },
    {
      "ids": ["EFF-03", "EFF-07"],
      "type": "logical",
      "description": "Executing Minimal Risk Maneuvers swiftly (EFF-03) may contradict the need for smooth transitions during emergency maneuvers (EFF-07)."
    }
  ],
  "positions": [
    {
      "id": "SAF-04",
